import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds exact half cents to the even cent so invoices carry no upward bias", () => {
    expect(roundCents(12.5)).toBe(12);
    expect(roundCents(13.5)).toBe(14);
    expect(roundCents(0.5)).toBe(0);
  });

  it("rounds non-half fractions to the nearest cent", () => {
    expect(roundCents(12.49)).toBe(12);
    expect(roundCents(12.51)).toBe(13);
    expect(roundCents(7)).toBe(7);
  });

  it("applies the same half-to-even rule to credits and refunds", () => {
    expect(roundCents(-2.5)).toBe(-2);
    expect(roundCents(-3.5)).toBe(-4);
    expect(roundCents(-2.6)).toBe(-3);
  });
});

